CREATE TABLE "treinamento_servico_validador" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"versao_id" uuid NOT NULL,
	"rodada" integer NOT NULL,
	"posicao" integer NOT NULL,
	"equipe_id" uuid NOT NULL,
	"decisao" text,
	"usuario_id" uuid,
	"decidida_em" timestamp with time zone,
	"motivo" text,
	"assinatura_path" text,
	CONSTRAINT "treinamento_servico_validador_versao_rodada_equipe_key" UNIQUE("versao_id","rodada","equipe_id"),
	CONSTRAINT "treinamento_servico_validador_rodada_check" CHECK ("treinamento_servico_validador"."rodada" > 0 and "treinamento_servico_validador"."posicao" > 0),
	CONSTRAINT "treinamento_servico_validador_decisao_check" CHECK ("treinamento_servico_validador"."decisao" is null or "treinamento_servico_validador"."decisao" in ('aprovou', 'recusou')),
	CONSTRAINT "treinamento_servico_validador_decisao_completa" CHECK (("treinamento_servico_validador"."decisao" is null) = ("treinamento_servico_validador"."usuario_id" is null) and ("treinamento_servico_validador"."decisao" is null) = ("treinamento_servico_validador"."decidida_em" is null) and ("treinamento_servico_validador"."decisao" is null) = ("treinamento_servico_validador"."assinatura_path" is null)),
	CONSTRAINT "treinamento_servico_validador_recusa_com_motivo" CHECK ("treinamento_servico_validador"."decisao" is distinct from 'recusou' or ("treinamento_servico_validador"."motivo" is not null and btrim("treinamento_servico_validador"."motivo") <> ''))
);
